<script setup>
import {useTableLayout} from '../../shared/composables/tableLayout.js'
const {pinTableActions}=useTableLayout()




import {computed, ref} from 'vue'
import MarkdownContent from '../../shared/components/MarkdownContent.vue'
import SQLPlanPreview from '../../deploy/components/SQLPlanPreview.vue'
import OperationPlanPreview from '../../deploy/components/OperationPlanPreview.vue'
import NacosPlanPreview from '../../deploy/components/NacosPlanPreview.vue'
import RedisPlanPreview from '../../deploy/components/RedisPlanPreview.vue'
const props=defineProps({plan:{type:Object,required:true}}),tab=ref('changes')
const changes=computed(()=>props.plan.scope?.changes||props.plan.version?.changes||[])
const research=computed(()=>props.plan.template?.workbench==='research')
const names={code:'代码',mysql:'SQL',nacos:'配置',redis:'Redis','data-sync':'数据同步',manual:'自定义记录'}
const manualNodes=computed(()=>(props.plan.nodes||[]).filter(n=>n.kind==='manual'&&n.change_ids?.length))
