import {ref as _viewRef} from 'vue'
const _view1=_viewRef([])
const _view2=_viewRef([])


import {Accordion,AccordionContent,AccordionItem,AccordionTrigger,Button,Empty,EmptyContent,EmptyDescription,EmptyHeader,Table,TableBody,TableCell,TableHead,TableHeader,TableRow,Tabs,TabsContent,TabsList,TabsTrigger} from '../../shared/shadcn-ui.js'
</script>
