l>{{c.service||'—'}}</small></div></template></div></TableCell><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(true)}"><template v-for="{record:c,rowIndex:rowIndex} in [{record,rowIndex}]"><div>{{names[c.kind]||c.kind}}</div></template></div></TableCell><TableCell class="align-top"><div class="min-w-0 break-words"><template v-for="{record:c,rowIndex:rowIndex} in [{record,rowIndex}]"><MarkdownContent :content="c.summary||c.reference||'未填写'"/></template></div></TableCell><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(true)}"><template v-for="{record:c,rowIndex:rowIndex} in [{record,rowIndex}]"><div>{{({low:'低',medium:'中',high:'高'})[c.risk_level]||c.risk_level||'未填写'}}</div></template></div></TableCell><TableCell class="align-top"><div class="min-w-0 break-words"><template v-for="{record:c,rowIndex:rowIndex} in [{record,rowIndex}]"><MarkdownContent :content="c.rollback_plan||'未填写，需核对'" label="回退方案"/></template></div></TableCell></TableRow></template><TableRow v-if="!(((changes)||[]).map((c,rowIndex)=>({...c,__rowKey:c.id}))||[]).length"><TableCell :colspan="5"><Empty><EmptyHeader><EmptyDescription>本次没有关联变更；请核对固定应用的制品与部署目标。</EmptyDescription></EmptyHeader></Empty></TableCell></TableRow></TableBody></Table></div></div></div><template v-if="tab==='apps'"><div class="r-table"><div class="console-table min-w-0 max-w-full"><div class="max-w-full overflow-auto rounded-lg border" :style="{maxHeight:({x:800}).y?({x:800}).y+'px':undefined}"><Table class="table-fixed min-w-[var(--table-min-width)]" :style="{'--table-min-width':(({x:800}).x||({x:800}).minWidth||800)+'px'}"><TableHeader><TableRow><TableHead :style="{width:(240)+'px'}">应用</TableHead><TableHead :style="{width:(200)+'px'}">锁定制品 / 代码版本</TableHead><TableHead :style="{width:(180)+'px'}">目标 / 策略</TableHead><TableHead :style="{width:(180)+'px'}">健康检查</TableHead></TableRow></TableHeader><TableBody><template v-for="(record,rowIndex) in (((plan.services||[])||[]).map((a,rowIndex)=>({...a,__rowKey:a.service}))||[])" :key="typeof (&quot;__rowKey&quot;)==='function'?(&quot;__rowKey&quot;)(record):record[&quot;__rowKey&quot;]??rowIndex"><TableRow><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(true)}"><template v-for="{record:a,rowIndex:rowIndex} in [{record,rowIndex}]"><div>{{a.service}}</div></template></div></TableCell><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(true)}"><template v-for="{record:a,rowIndex:rowIndex} in [{record,rowIndex}]"><div>制品 #{{a.artifact?.id}} · {{a.artifact?.version||a.artifact?.commit||'—'}}<small>{{a.artifact?.digest||a.artifact?.sha256||'—'}}</small></div></template></div></TableCell><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(true)}"><template v-for="{record:a,rowIndex:rowIndex} in [{record,rowIndex}]"><div>{{a.target?.environment||plan.environment?.name}} · {{a.target?.target_type||'主机'}}<small>{{a.target?.hosts?.join('、')||a.target?.host_group||a.target?.deploy_config?.app_id||'—'}} · {{a.target?.strategy||'默认策略'}} · 每批 {{a.target?.batch_size||1}}</small></div></template></div></TableCell><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(true)}"><template v-for="{record:a,rowIndex:rowIndex} in [{record,rowIndex}]"><div>{{a.target?.health_url||'未配置 HTTP 健康检查'}}</div></template></div></TableCell></TableRow></template><TableRow v-if="!(((plan.services||[])||[]).map((a,rowIndex)=>({...a,__rowKey:a.service}))||[]).length"><TableCell :colspan="4"><Empty><EmptyHeader><EmptyDescription>{{research?'前置流程尚未冻结最终部署制品，代码范围见下方。':'本次不包含应用部署节点。'}}</EmptyDescription></EmptyHeader></Empty></TableCell></TableRow></TableBody></Table></div></div></div><div v-if="research" class="r-table"><div class="console-table min-w-0 max-w-full"><div class="max-w-full overflow-auto rounded-lg border" :style="{maxHeight:({x:640}).y?({x:640}).y+'px':undefined}"><Table class="table-fixed min-w-[var(--table-min-width)]" :style="{'--table-min-width':(({x:640}).x||({x:640}).minWidth||640)+'px'}"><TableHeader><TableRow><TableHead :style="{width:(240)+'px'}">代码变更 / 应用</TableHead><TableHead :style="{width:(200)+'px'}">来源分支</TableHead><TableHead :style="{width:(200)+'px'}">本次目标分支</TableHead></TableRow></TableHeader><TableBody><template v-for="(record,rowIndex) in (((changes.filter(c=>c.kind==='code'))||[]).map((c,rowIndex)=>({...c,__rowKey:c.id}))||[])" :key="typeof (&quot;__rowKey&quot;)==='function'?(&quot;__rowKey&quot;)(record):record[&quot;__rowKey&quot;]??rowIndex"><TableRow><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(true)}"><template v-for="{record:c,rowIndex:rowIndex} in [{record,rowIndex}]"><div>{{c.service}} · {{c.title}}</div></template></div></TableCell><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(true)}"><template v-for="{record:c,rowIndex:rowIndex} in [{record,rowIndex}]"><div>{{c.reference||'未填写'}}</div></template></div></TableCell><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(true)}"><template v-for="{record:c,rowIndex:rowIndex} in [{record,rowIndex}]"><div>{{plan.nodes?.find(n=>n.policies?.[c.service])?.policies?.[c.service]?.target_branch||'人工确认，未配置自动合并'}}</div></template></div></TableCell></TableRow></template><TableRow v-if="!(((changes.filter(c=>c.kind==='code'))||[]).map((c,rowIndex)=>({...c,__rowKey:c.id}))||[]).length"><TableCell :colspan="3"><Empty><EmptyHeader><EmptyDescription>暂无数据</EmptyDescription></EmptyHeader></Empty></TableCell></TableRow></TableBody></Table></div></div></div></template><template v-if="tab==='sql'"><SQLPlanPreview :plans="plan.sql_plans"/><template v-if="!plan.sql_plans?.length"><article v-for="c in changes.filter(c=>c.sql)" :key="c.id"><b>#{{c.id}} · {{c.service}} / {{c.sql.resource_alias}}</b><pre>{{c.sql.content}}</pre><Accordion v-if="c.sql.environment_overrides?.length" class="platform-collapse" type="multiple" :model-value="(_view1||[]).map(String)" @update:model-value="_view1=$event"><AccordionItem :value="String(&quot;panel&quot;)"><AccordionTrigger>SQL 环境例外 · {{c.sql.environment_overrides.length}}</AccordionTrigger><AccordionContent force-mount v-show="!(!(_view1||[]).map(String).includes(String(&quot;panel&quot;)))"><div v-for="e in c.sql.environment_overrides" :key="e.environment"><b>{{e.environment}} · {{e.skip?'无需执行':'专用 SQL'}}</b><p>{{e.reason}}</p><pre v-if="!e.skip">{{e.content}}</pre></div></AccordionContent></AccordionItem></Accordion><p class="r-muted">允许影响 {{c.sql.max_affected_rows}} 行；尚无执行预检快照，不代表已验证目标表结构或影响行数。</p></article><p v-if="!changes.some(c=>c.sql)" class="r-muted">本次无 SQL 或数据同步变更。</p></template></template><template v-if="tab==='config'"><NacosPlanPreview :plans="plan.nacos_plans||[]"/><RedisPlanPreview :plans="plan.redis_plans||[]"/><template v-if="!plan.nacos_plans?.length"><article v-for="c in changes.filter(c=>c.nacos)" :key="c.id"><b>#{{c.id}} · {{c.service}} / {{c.nacos.resource_alias}}</b><p class="r-muted">默认 {{c.nacos.data_id}} / {{c.nacos.group}}；最终目标按环境绑定解析，当前未冻结远端差异。</p><div class="r-table"><div class="console-table min-w-0 max-w-full"><div class="max-w-full overflow-auto rounded-lg border" :style="{maxHeight:({x:536}).y?({x:536}).y+'px':undefined}"><Table class="table-fixed min-w-[var(--table-min-width)]" :style="{'--table-min-width':(({x:536}).x||({x:536}).minWidth||536)+'px'}"><TableHeader><TableRow><TableHead :style="{width:(180)+'px'}">配置项</TableHead><TableHead :class="(pinTableActions?'right':undefined)==='right'?'sticky right-0 z-10 bg-background':(pinTableActions?'right':undefined)==='left'?'sticky left-0 z-10 bg-background':''" :style="{width:(176)+'px'}">操作</TableHead><TableHead :style="{width:(180)+'px'}">期望值</TableHead></TableRow></TableHeader><TableBody><template v-for="(record,rowIndex) in (((c.nacos.entries||[])||[]).map((entry,rowIndex)=>({...entry,__rowKey:entry.key}))||[])" :key="typeof (&quot;__rowKey&quot;)==='function'?(&quot;__rowKey&quot;)(record):record[&quot;__rowKey&quot;]??rowIndex"><TableRow><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(true)}"><template v-for="{record:entry,rowIndex:rowIndex} in [{record,rowIndex}]"><div>{{entry.key}}</div></template></div></TableCell><TableCell class="align-top" :class="(pinTableActions?'right':undefined)==='right'?'sticky right-0 z-10 bg-background':(pinTableActions?'right':undefined)==='left'?'sticky left-0 z-10 bg-background':''"><div class="min-w-0 break-words" :class="{truncate:!!(false)}"><template v-for="{record:entry,rowIndex:rowIndex} in [{record,rowIndex}]"><div>{{entry.action==='remove'?'移除':entry.action==='delete'?'删除':'设置值'}}</div></template></div></TableCell><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(true)}"><template v-for="{record:entry,rowIndex:rowIndex} in [{record,rowIndex}]"><div>{{entry.value}}</div></template></div></TableCell></TableRow></template><TableRow v-if="!(((c.nacos.entries||[])||[]).map((entry,rowIndex)=>({...entry,__rowKey:entry.key}))||[]).length"><TableCell :colspan="3"><Empty><EmptyHeader><EmptyDescription>暂无数据</EmptyDescription></EmptyHeader></Empty></TableCell></TableRow></TableBody></Table></div></div></div></article></template><template v-if="!plan.redis_plans?.length"><article v-for="c in changes.filter(c=>c.redis)" :key="c.id"><b>#{{c.id}} · {{c.service}} / {{c.redis.resource_alias}}</b><pre>{{c.redis.commands}}</pre></article></template><p v-if="!plan.nacos_plans?.length&&!plan.redis_plans?.length&&!changes.some(c=>c.nacos||c.redis)" class="r-muted">本次无配置或 Redis 变更。</p></template><Accordion v-if="plan.resource_targets?.length" class="platform-collapse" type="multiple" :model-value="(_view2||[]).map(String)" @update:model-value="_view2=$event"><AccordionItem :value="String(&quot;panel&quot;)"><AccordionTrigger>本次环境解析的资源目标</AccordionTrigger><AccordionContent force-mount v-show="!(!(_view2||[]).map(String).includes(String(&quot;panel&quot;)))"><div class="r-table"><div class="console-table min-w-0 max-w-full"><div class="max-w-full overflow-auto rounded-lg border" :style="{maxHeight:({x:600}).y?({x:600}).y+'px':undefined}"><Table class="table-fixed min-w-[var(--table-min-width)]" :style="{'--table-min-width':(({x:600}).x||({x:600}).minWidth||600)+'px'}"><TableHeader><TableRow><TableHead :style="{width:(240)+'px'}">应用 / 逻辑资源</TableHead><TableHead :style="{width:(180)+'px'}">目标环境</TableHead><TableHead :style="{width:(180)+'px'}">实际目标</TableHead></TableRow></TableHeader><TableBody><template v-for="(record,rowIndex) in (((plan.resource_targets)||[]).map((t,rowIndex)=>({...t,__rowKey:t.node_id+':'+t.change_id}))||[])" :key="typeof (&quot;__rowKey&quot;)==='function'?(&quot;__rowKey&quot;)(record):record[&quot;__rowKey&quot;]??rowIndex"><TableRow><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(true)}"><template v-for="{record:t,rowIndex:rowIndex} in [{record,rowIndex}]"><div>{{t.service}} / {{t.alias}}<small>{{t.group_name||'应用资源绑定'}}</small></div></template></div></TableCell><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(true)}"><template v-for="{record:t,rowIndex:rowIndex} in [{record,rowIndex}]"><div>{{t.environment}}</div></template></div></TableCell><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(true)}"><template v-for="{record:t,rowIndex:rowIndex} in [{record,rowIndex}]"><div>{{t.label}}</div></template></div></TableCell></TableRow></template><TableRow v-if="!(((plan.resource_targets)||[]).map((t,rowIndex)=>({...t,__rowKey:t.node_id+':'+t.change_id}))||[]).length"><TableCell :colspan="3"><Empty><EmptyHeader><EmptyDescription>暂无数据</EmptyDescription></EmptyHeader></Empty></TableCell></TableRow></TableBody></Table></div></div></div></AccordionContent></AccordionItem></Accordion><OperationPlanPreview :nodes="plan.nodes||[]"/><p v-for="w in plan.warnings||[]" :key="w" class="r-muted">提示：{{w}}</p></section></template>
